const toolError=message=>({content:[{type:'text',text:message}],isError:true});
function validate(spec,args){
 if(!args||typeof args!=='object'||Array.isArray(args))throw Error('Arguments must be an object.');
 for(const k of spec.inputSchema.required)if(!(k in args))throw Error('Missing required argument: '+k);
 for(const [k,v]of Object.entries(args)){
  const p=spec.inputSchema.properties[k];if(!p)throw Error('Unknown argument: '+k);if(p.enum&&!p.enum.includes(v))throw Error('Unsupported value for '+k);
  if(p.type==='string'&&typeof v!=='string'||p.type==='integer'&&!Number.isInteger(v)||p.type==='boolean'&&typeof v!=='boolean'||p.type==='number'&&(typeof v!=='number'||!Number.isFinite(v)))throw Error('Invalid type for '+k);
  if(p.format==='uuid'&&!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v))throw Error(k+' must be a resolved UUID.');
  if(p.minimum!==undefined&&v<p.minimum||p.maximum!==undefined&&v>p.maximum)throw Error(k+' is outside the supported range.');
 }
}
async function upstream(spec,args,env){
 if(!env.RAPIDAPI_KEY)return toolError('API key is not configured.');
 let response;try{response=await fetch('https://mcp.rapidapi.com',{method:'POST',headers:{'content-type':'application/json','accept':'application/json, text/event-stream','x-api-host':'hyprace-api.p.rapidapi.com','x-api-key':env.RAPIDAPI_KEY},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:spec.upstreamName,arguments:{...args,_endpoint:spec.endpoint,_method:'GET'}}}),signal:AbortSignal.timeout(25000)});}catch{return toolError('Hyprace request failed or timed out. Retry later.');}
 if(!response.ok)return toolError('Hyprace HTTP '+response.status+'. '+(response.status===429?'Rate limit reached.':response.status===401||response.status===403?'Check API key and subscription.':'Provider request failed.'));
 const raw=(await response.text()).split(env.RAPIDAPI_KEY).join('[redacted]');if(raw.length>1500000)return toolError('Result too large. Request a smaller page.');
 let data;try{data=JSON.parse(raw);}catch{for(const line of raw.split(/\r?\n/)){if(line.startsWith('data:'))try{const d=JSON.parse(line.slice(5).trim());if(d.id===1)data=d;}catch{}}}
 if(!data)return toolError('Unsupported provider response format.');
 if(data.error)return toolError('Hyprace MCP error: '+String(data.error.message??'Unknown error').slice(0,500));
 const content=data.result?.content?.filter(c=>c.type==='text').map(c=>({type:'text',text:c.text}));if(!content?.length)return toolError('Provider returned no readable result.');
 content.push({type:'text',text:JSON.stringify({source:'Hyprace via RapidAPI',endpoint:spec.endpoint,retrieved_at:new Date().toISOString(),coverage_note:'Provider records only; no telemetry or causal explanations.'})});
 return {content,isError:data.result.isError===true};
}
